  mt([("twelfth", "12-те"), ("twentieth", "20-те"), ("thirtieth", "30-те"), ("tenth", "10-те")], "Ten → tenth, twelve → twelfth, twenty → twentieth.", "З'єднайте слово з числом"),
  liu("What's the date today?", "Прослухайте. Що питає людина?", ["Яке сьогодні число", "Який сьогодні день тижня", "Котра година"], "The date — число."),
  liu("It's the fifth of October.", "Прослухайте. Яка дата?", ["5 жовтня", "15 жовтня", "5 серпня"], "The fifth of October."),
  liu("It's the twenty-first of December.", "Прослухайте. Яка дата?", ["21 грудня", "20 грудня", "12 грудня"], "Twenty-first — двадцять перше."),
